class BowlingGame:
    def __init__(self):
        self.rolls = []
        self.frames = []
        self.current = []
        self.game_over = False

    def roll(self, pins):
        if self.game_over:
            raise Exception("Cannot roll after the game has 10 frames")
        if pins < 0:
            raise Exception("Negative roll is invalid")
        if pins > 10:
            raise Exception("Pin count exceeds 10")

        if len(self.frames) < 9:
            if len(self.current) == 1 and self.current[0] + pins > 10:
                raise Exception("Frame cannot score more than 10 points")
        else:
            self._validate_tenth_frame(pins)

        self.rolls.append(pins)
        self.current.append(pins)

        if len(self.frames) < 9:
            if len(self.current) == 1 and self.current[0] == 10:
                self._complete_frame()
            elif len(self.current) == 2:
                self._complete_frame()
        else:
            self._finish_tenth_frame_if_done()

    def _validate_tenth_frame(self, pins):
        current = self.current
        if len(current) == 1 and current[0] < 10 and current[0] + pins > 10:
            raise Exception("Frame cannot score more than 10 points")
        if (
            len(current) == 2
            and current[0] == 10
            and current[1] < 10
            and current[1] + pins > 10
        ):
            raise Exception("Frame cannot score more than 10 points")

    def _finish_tenth_frame_if_done(self):
        current = self.current
        if len(current) == 2:
            if current[0] < 10 and current[0] + current[1] < 10:
                self._complete_frame()
                self.game_over = True
        elif len(current) == 3:
            self._complete_frame()
            self.game_over = True

    def _complete_frame(self):
        self.frames.append(self.current)
        self.current = []

    def score(self):
        if not self.game_over:
            raise Exception("Score cannot be determined until the game is complete")
        rolls = self.rolls
        total = 0
        i = 0
        for _ in range(10):
            if rolls[i] == 10:
                total += rolls[i] + rolls[i + 1] + rolls[i + 2]
                i += 1
            else:
                total += rolls[i] + rolls[i + 1]
                if rolls[i] + rolls[i + 1] == 10:
                    total += rolls[i + 2]
                i += 2
        return total

